+
+    button:focus-visible {
+      outline: none;
+      box-shadow: 0 0 0 4px var(--focus), 0 14px 30px rgba(37, 99, 235, 0.22);
+    }
+
+    .status {
+      min-height: 1.2em;
+      margin: 0;
+      color: #0f766e;
+      font-weight: 600;
+    }
+  </style>
