+<body>
+  <main class="support-card">
+    <p class="eyebrow">Support</p>
+    <h1>Contact our team</h1>
+    <p class="lead">Send us a note and we&apos;ll get back to you as soon as possible.</p>
+
+    <form id="supportForm" novalidate>
+      <div class="form-field">
+        <label for="fullName">Full name</label>
+        <input id="fullName" name="fullName" type="text" autocomplete="name" placeholder="Jane Doe" required />
+        <p class="error-message" id="fullNameError" aria-live="polite"></p>
+      </div>
+
+      <div class="form-field">
+        <label for="email">Email address</label>
+        <input id="email" name="email" type="email" autocomplete="email" placeholder="jane@company.com" required />
+        <p class="error-message" id="emailError" aria-live="polite"></p>
+      </div>
+
+      <div class="form-field">
+        <label for="phone">Phone number</label>
+        <input id="phone" name="phone" type="tel" autocomplete="tel" placeholder="(555) 123-4567" aria-describedby="phoneHelp phoneError" />
+        <p class="helper-text" id="phoneHelp">Optional. Use a phone number with 10 digits, like (555) 123-4567.</p>
+        <p class="error-message" id="phoneError" aria-live="polite"></p>
+      </div>
+
+      <div class="submit-row">
+        <button type="submit">Send message</button>
+        <p class="status" id="formStatus" aria-live="polite"></p>
+      </div>
+    </form>
+  </main>
+
+  <script>
