+      if (!valid) {
+        status.textContent = '';
+        return;
+      }
+
+      form.reset();
+      Object.keys(fields).forEach((name) => clearError(fields[name], errors[name]));
+      status.textContent = 'Your message has been sent.';
+    });
+  </script>
+</body>
+</html>
